head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30651";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30651.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_beforeName", fn: function () { return String((dma_pageContext.get("beforeName") ?? "")); } },
        { childId: "ipt_comCode", fn: function () { return String((dma_pageContext.get("comCode") ?? "")); } },
        { childId: "ipt_comName", fn: function () { return String((dma_pageContext.get("comName") ?? "")); } },
        { childId: "ipt_name", fn: function () { return String((dma_pageContext.get("name") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    if ('null' === 'end') {

    }
    if ($c.util.getComponent("dma_submitReq").get("beforeName") !== '') {
        self.before.innerHTML = $c.util.getComponent("dma_submitReq").get("beforeName");
    }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_submit, tx_searchPerson) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_comCode_onclick
 * @description ipt_comCode 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_comCode_onclick = function(e){
    try {
        scwin.initField()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30651.ipt_comCode_onclick' }); }
};

/**
 * @method
 * @name ipt_comCode_onkeypress
 * @description ipt_comCode onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_comCode_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if (event.keyCode===13){scwin.searchCode('read'); return false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30651.ipt_comCode_onkeypress' }); }
};

/**
 * @method
 * @name btn_go_Stock_onclick
 * @description btn_go_Stock 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_go_Stock_onclick = function(e){
    try {
        go_Stock(2)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30651.btn_go_Stock_onclick' }); }
};

/**
 * @method
 * @name btn_searchPerson_onclick
 * @description btn_searchPerson 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchPerson_onclick = async function(e){
    try {
        await scwin.searchPerson()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30651.btn_searchPerson_onclick' }); }
};

/**
 * @method
 * @name btn_searchCode_onclick
 * @description btn_searchCode 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_searchCode_onclick = function(e){
    try {
        scwin.searchCode()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30651.btn_searchCode_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_submit = async function () {
    const sbmOptions = {
        id: "tx_submit",
        method: "post",
        action: "/PersonInfo.do",
        ref: "dma_submitReq",
        target: "dlt_List=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchPerson
 * @description search Person 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchPerson = async function () {
    const sbmOptions = {
        id: "tx_searchPerson",
        method: "post",
        action: "/PersonInfo.do",
        ref: "dma_searchPersonReq",
        target: "dlt_List=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initField
 * @description init Field 처리
 * @returns {void}
 * @hidden N
 */
scwin.initField = function () {
    const f = (document.form || { elements: [] });
    $c.util.getComponent("ipt_name").setValue("");
    f.birthday.value = "";
};

